/// Returns `true` if the given month (1–12) has 30 days:
/// April (4), June (6), September (9), or November (11).
/// For any other month in the range 1–12, returns `false`.
fn is_month_with_30_days(month: i32) -> bool {
    matches!(month, 4 | 6 | 9 | 11)
}

